// Telegram voice notes arrive as .oga; transcription APIs accept the same Ogg/Opus data as .ogg
const data = $input.item.binary.data;
const isOga = data.fileExtension === 'oga' || /\.oga$/i.test(data.fileName || '');
const fixed = isOga ? { ...data, fileName: 'voice.ogg', fileExtension: 'ogg', mimeType: 'audio/ogg' } : data;
return { json: $json, binary: { data: fixed } };

// Turns any Telegram message into a text prompt for the agent.
// A photo keeps its binary so the agent sees the image; audio is dropped after transcription.
const m = $('Telegram Trigger').item.json.message;
let prompt;
if (m.text) {
  prompt = m.text;
} else if (m.photo) {
  prompt = m.caption || '[The user sent a photo without a caption. Look at it and respond.]';
} else if (m.voice || m.audio) {
  const transcript = String($json.text || '').trim();
  prompt = transcript
    ? '[Voice message, transcribed] ' + transcript
    : '[The user sent a voice message that could not be transcribed. Ask them to send it as text.]';
} else {
  const skip = ['message_id', 'from', 'chat', 'date', 'caption', 'entities', 'caption_entities'];
  const kind = m.sticker
    ? ('sticker ' + (m.sticker.emoji || '')).trim()
    : Object.keys(m).filter((k) => !skip.includes(k)).join(', ') || 'unknown';
  prompt = '[The user sent something you cannot read yet (' + kind + '). '
    + 'Reply briefly that for now you understand text, photos and voice messages.]';
}
const item = { json: { prompt } };
if (m.photo) item.binary = $input.item.binary;
return item;

// Telegram allows 4096 characters per message: split on paragraph, line or word boundaries,
// then turn the agent's basic Markdown into Telegram HTML.
const LIMIT = 3800;
let rest = String($input.first().json.output || '').trim() || '...';
const chunks = [];
while (rest.length > LIMIT) {
  let cut = rest.lastIndexOf('\n\n', LIMIT);
  if (cut < LIMIT / 2) cut = rest.lastIndexOf('\n', LIMIT);
  if (cut < LIMIT / 2) cut = rest.lastIndexOf(' ', LIMIT);
  if (cut <= 0) cut = LIMIT;
  chunks.push(rest.slice(0, cut).trim());
  rest = rest.slice(cut).trim();
}
chunks.push(rest);
const toHtml = (s) => s
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/^#{1,6}\s+(.+)$/gm, '<b>$1</b>')
  .replace(/\*\*([^*\n]+?)\*\*/g, '<b>$1</b>')
  .replace(/`([^`\n]+?)`/g, '<code>$1</code>')
  .replace(/\[([^\]\n]+)\]\((https?:\/\/[^)\s"]+)\)/g, '<a href="$2">$1</a>');
return chunks.map((c) => ({ json: { text: toHtml(c) }, pairedItem: 0 }));
